1	<!DOCTYPE html>
2	<html lang="en">
3	<head>
4	<meta charset="utf-8" />
5	<meta name="viewport" content="width=device-width, initial-scale=1" />
6	<title>Bookmarks — prototype 01 (save a link)</title>
7	<style>
8	  :root { --line:#e2e2e6; --muted:#6b6b72; --accent:#3b5bdb; --bg:#f7f7f9; }
9	  * { box-sizing: border-box; }
10	  body { font-family: -apple-system, Segoe UI, Roboto, Helvetica, Arial, sans-serif;
11	         margin: 0; background: var(--bg); color: #1a1a1e; }
12	  .wrap { max-width: 720px; margin: 0 auto; padding: 32px 20px 80px; }
13	  h1 { font-size: 20px; margin: 0 0 4px; }
14	  .sub { color: var(--muted); font-size: 13px; margin: 0 0 24px; }
15	
16	  .saver { background: #fff; border: 1px solid var(--line); border-radius: 12px;
17	           padding: 18px; }
18	  .row { display: flex; gap: 8px; }
19	  input[type=url], input[type=text], textarea {
20	      width: 100%; padding: 10px 12px; border: 1px solid var(--line);
21	      border-radius: 8px; font-size: 14px; font-family: inherit; background:#fff; }
22	  textarea { resize: vertical; min-height: 60px; }
23	  button { border: 0; border-radius: 8px; padding: 10px 16px; font-size: 14px;
24	           cursor: pointer; }
25	  .primary { background: var(--accent); color: #fff; }
26	  .primary:disabled { opacity: .5; cursor: default; }
27	
28	  .fields { margin-top: 14px; display: none; }
29	  .fields.show { display: block; }
30	  label { display: block; font-size: 12px; color: var(--muted); margin: 12px 0 4px; }
31	  .fetching { margin-top: 14px; font-size: 13px; color: var(--muted); display:none; }
32	  .fetching.show { display: block; }
33	  .badge { display:inline-block; font-size:11px; color:var(--accent);
34	           background:#eaefff; border-radius:6px; padding:2px 7px; margin-left:6px; }
35	
36	  .list { margin-top: 32px; }
37	  .list h2 { font-size: 13px; color: var(--muted); text-transform: uppercase;
38	             letter-spacing: .04em; margin: 0 0 12px; }
39	  .card { background:#fff; border:1px solid var(--line); border-radius:10px;
40	          padding:14px 16px; margin-bottom:10px; }
41	  .card .title { font-size:15px; font-weight:600; margin:0 0 2px; }
42	  .card .url { font-size:12px; color:var(--accent); word-break:break-all; }
43	  .card .desc { font-size:13px; color:#3a3a42; margin:8px 0 0; }
44	  .empty { color: var(--muted); font-size:14px; padding: 20px 0; }
45	  .save-actions { margin-top:16px; display:flex; gap:8px; align-items:center; }
