50	<body>
51	<div class="wrap">
52	  <h1>My Bookmarks</h1>
53	  <p class="sub">Prototype 01 — saving a link</p>
54	
55	  <div class="saver">
56	    <div class="row">
57	      <input id="urlInput" type="url" placeholder="Paste a link here…" autocomplete="off" />
58	      <button id="addBtn" class="primary">Add</button>
59	    </div>
60	
61	    <div id="fetching" class="fetching">Reading the page…</div>
62	
63	    <div id="fields" class="fields">
64	      <label>Title <span class="badge">filled in for you</span></label>
65	      <input id="titleField" type="text" />
66	      <label>Description <span class="badge">filled in for you</span></label>
67	      <textarea id="descField"></textarea>
68	      <div class="save-actions">
69	        <button id="saveBtn" class="primary">Save bookmark</button>
70	        <button id="cancelBtn" style="background:#eee;color:#333">Cancel</button>
71	      </div>
72	    </div>
73	  </div>
74	
75	  <div class="list">
76	    <h2>Saved</h2>
77	    <div id="cards"></div>
78	  </div>
79	</div>
80	
81	<script>
82	  // --- Simulated "read the page" metadata. Phase-1 prototype: no real network. ---
83	  const KNOWN = {
84	    "smittenkitchen.com": {
85	      title: "Simplest Brothy Beans and Rice",
86	      desc: "A weeknight one-pot dinner: creamy beans simmered with garlic and herbs, served over rice. Ready in about 40 minutes."
87	    },
88	    "nytimes.com": {
89	      title: "How to Read More Books This Year",
90	      desc: "Practical habits from lifelong readers for fitting more reading into a busy schedule."
91	    },
92	    "github.com": {
93	      title: "ripgrep — recursively search directories for a regex pattern",
94	      desc: "A line-oriented search tool that recursively searches your current directory for a regex pattern while respecting gitignore rules."
95	    },
96	    "figma.com": {
97	      title: "Figma: the collaborative interface design tool",
98	      desc: "Design, prototype, and gather feedback all in one place with Figma."
99	    }
100	  };
101	
102	  function lookup(url) {
103	    let host = "";
104	    try { host = new URL(url).hostname.replace(/^www\./, ""); } catch (e) {}
105	    if (KNOWN[host]) return KNOWN[host];
106	    // Fallback: derive a rough title from the address, empty description.
107	    const nice = host ? host.split(".")[0] : "Saved page";
108	    return { title: nice.charAt(0).toUpperCase() + nice.slice(1) + " — page", desc: "" };
109	  }
110	
111	  const urlInput = document.getElementById("urlInput");
112	  const addBtn   = document.getElementById("addBtn");
113	  const fetching = document.getElementById("fetching");
114	  const fields   = document.getElementById("fields");
115	  const titleF   = document.getElementById("titleField");
116	  const descF    = document.getElementById("descField");
117	  const saveBtn  = document.getElementById("saveBtn");
118	  const cancelBtn= document.getElementById("cancelBtn");
119	  const cards    = document.getElementById("cards");
120	
121	  let pendingUrl = "";
122	  const saved = [];
123	
124	  function renderList() {
125	    if (saved.length === 0) {
126	      cards.innerHTML = '<div class="empty">Nothing saved yet.</div>';
127	      return;
128	    }
129	    cards.innerHTML = "";
130	    saved.forEach((b, i) => {
131	      const c = document.createElement("div");
132	      c.className = "card" + (i === 0 && b._new ? " just-saved" : "");
133	      b._new = false;
134	      c.innerHTML =
135	        '<p class="title"></p><div class="url"></div>' +
136	        (b.desc ? '<p class="desc"></p>' : "");
137	      c.querySelector(".title").textContent = b.title;
138	      c.querySelector(".url").textContent = b.url;
139	      if (b.desc) c.querySelector(".desc").textContent = b.desc;
140	      cards.appendChild(c);
141	    });
142	  }
143	
144	  function startAdd() {
145	    const url = urlInput.value.trim();
146	    if (!url) return;
147	    pendingUrl = url;
148	    fields.classList.remove("show");
149	    fetching.classList.add("show");
150	    // Simulate the brief moment of reading the page.
151	    setTimeout(() => {
152	      const meta = lookup(url);
153	      titleF.value = meta.title;
154	      descF.value = meta.desc;
155	      fetching.classList.remove("show");
156	      fields.classList.add("show");
157	      titleF.focus();
158	      titleF.select();
159	    }, 650);
160	  }
161	
162	  addBtn.addEventListener("click", startAdd);
163	  urlInput.addEventListener("keydown", e => { if (e.key === "Enter") startAdd(); });
164	
165	  saveBtn.addEventListener("click", () => {
166	    saved.unshift({ url: pendingUrl, title: titleF.value.trim(),
167	                    desc: descF.value.trim(), _new: true });
168	    urlInput.value = ""; titleF.value = ""; descF.value = "";
169	    pendingUrl = "";
170	    fields.classList.remove("show");
171	    renderList();
172	    urlInput.focus();
173	  });
174	
175	  cancelBtn.addEventListener("click", () => {
176	    fields.classList.remove("show");
177	    titleF.value = ""; descF.value = "";
178	    urlInput.focus();
179	  });
180	
181	  renderList();
182	</script>
183	</body>
184	</html>
