72	<body>
73	<div class="wrap">
74	  <h1>My Bookmarks</h1>
75	  <p class="sub">Prototype 02 — adding labels while saving</p>
76	
77	  <div class="switch">
78	    <button data-style="A" class="on">Style A</button>
79	    <button data-style="B">Style B</button>
80	    <button data-style="C">Style C</button>
81	  </div>
82	  <div class="styleName" id="styleName"></div>
83	
84	  <div class="saver">
85	    <div class="row">
86	      <input id="urlInput" type="url" placeholder="Paste a link here…" autocomplete="off" />
87	      <button id="addBtn" class="primary">Add</button>
88	    </div>
89	    <div id="fetching" class="fetching">Reading the page…</div>
90	    <div id="fields" class="fields">
91	      <label class="fld">Title</label>
92	      <input id="titleField" type="text" />
93	      <label class="fld">Description</label>
94	      <textarea id="descField"></textarea>
95	      <label class="fld">Labels</label>
96	      <div id="labelArea"></div>
97	      <div class="save-actions">
98	        <button id="saveBtn" class="primary">Save bookmark</button>
99	        <button id="cancelBtn" class="ghost">Cancel</button>
100	      </div>
101	    </div>
102	  </div>
