110	<script>
111	  const KNOWN = {
112	    "smittenkitchen.com": { title: "Simplest Brothy Beans and Rice",
113	      desc: "A weeknight one-pot dinner: creamy beans simmered with garlic and herbs, over rice. About 40 minutes." },
114	    "nytimes.com": { title: "How to Read More Books This Year",
115	      desc: "Practical habits from lifelong readers for fitting more reading into a busy schedule." },
116	    "github.com": { title: "ripgrep — recursively search directories for a regex pattern",
117	      desc: "A line-oriented search tool that recursively searches your directory for a regex pattern." }
118	  };
119	  function lookup(url){ let h=""; try{h=new URL(url).hostname.replace(/^www\./,"");}catch(e){}
120	    if(KNOWN[h]) return KNOWN[h];
121	    const n=h?h.split(".")[0]:"Saved page";
122	    return {title:n.charAt(0).toUpperCase()+n.slice(1)+" — page", desc:""}; }
123	
124	  const EXISTING = ["work","reading","tools"];   // labels "used before"
125	  const STYLE_DESC = {
126	    A: "<b>Style A — type them, comma-separated.</b> One text box; type <code>recipes, dinner</code>. Simplest possible.",
127	    B: "<b>Style B — type + Enter makes a tag.</b> Each label becomes a removable pill; labels you've used before appear as one-tap suggestions.",
128	    C: "<b>Style C — pick from your existing labels.</b> Tap to select from labels you already use, and add a brand-new one when you need it."
129	  };
130	
131	  let style = "A";
132	  let pendingUrl = "";
133	  let currentLabels = [];
134	  const saved = [];
135	
136	  const urlInput=document.getElementById("urlInput"), addBtn=document.getElementById("addBtn"),
137	        fetching=document.getElementById("fetching"), fields=document.getElementById("fields"),
138	        titleF=document.getElementById("titleField"), descF=document.getElementById("descField"),
139	        labelArea=document.getElementById("labelArea"), saveBtn=document.getElementById("saveBtn"),
140	        cancelBtn=document.getElementById("cancelBtn"), cards=document.getElementById("cards"),
141	        styleName=document.getElementById("styleName");
142	
143	  document.querySelectorAll(".switch button").forEach(b=>{
144	    b.addEventListener("click",()=>{
145	      document.querySelectorAll(".switch button").forEach(x=>x.classList.remove("on"));
146	      b.classList.add("on"); style=b.dataset.style; styleName.innerHTML=STYLE_DESC[style];
147	      currentLabels=[]; if(fields.classList.contains("show")) renderLabelArea();
148	    });
149	  });
150	  styleName.innerHTML = STYLE_DESC["A"];
151	
152	  function renderLabelArea(){
153	    if(style==="A"){
154	      labelArea.innerHTML='<input id="labelText" type="text" placeholder="e.g. recipes, dinner" />';
155	      document.getElementById("labelText").value = currentLabels.join(", ");
156	    } else if(style==="B"){
157	      labelArea.innerHTML =
158	        '<div class="chips" id="chips"></div>'+
159	        '<div class="suggest">Used before: '+
160	          EXISTING.map(l=>'<button data-add="'+l+'">'+l+'</button>').join('')+'</div>';
161	      const chips=document.getElementById("chips");
162	      currentLabels.forEach(l=>{
163	        const c=document.createElement("span"); c.className="chip";
164	        c.innerHTML=l+' <button data-del="'+l+'">×</button>'; chips.appendChild(c);
165	      });
166	      const inp=document.createElement("input"); inp.id="chipInput";
167	      inp.placeholder=currentLabels.length?"":"type a label, press Enter"; chips.appendChild(inp);
168	      inp.addEventListener("keydown",e=>{
169	        if(e.key==="Enter"&&inp.value.trim()){ addLabel(inp.value.trim()); }
170	      });
171	      chips.querySelectorAll("[data-del]").forEach(x=>x.addEventListener("click",()=>{
172	        currentLabels=currentLabels.filter(l=>l!==x.dataset.del); renderLabelArea();
173	        document.getElementById("chipInput").focus();
174	      }));
175	      document.querySelectorAll("[data-add]").forEach(x=>x.addEventListener("click",()=>{
176	        addLabel(x.dataset.add); document.getElementById("chipInput").focus();
177	      }));
178	    } else {
179	      const all=[...new Set([...EXISTING,...currentLabels])];
180	      labelArea.innerHTML='<div class="picklist">'+
181	        all.map(l=>'<label class="'+(currentLabels.includes(l)?"sel":"")+'">'+
182	          '<input type="checkbox" data-pick="'+l+'" '+(currentLabels.includes(l)?"checked":"")+'>'+l+'</label>').join('')+
183	        '</div><div class="newlabel"><input id="newLabel" type="text" placeholder="+ new label, press Enter"></div>';
184	      labelArea.querySelectorAll("[data-pick]").forEach(x=>x.addEventListener("change",()=>{
185	        if(x.checked) currentLabels.push(x.dataset.pick);
186	        else currentLabels=currentLabels.filter(l=>l!==x.dataset.pick);
187	        renderLabelArea();
188	      }));
189	      document.getElementById("newLabel").addEventListener("keydown",e=>{
190	        const v=e.target.value.trim();
191	        if(e.key==="Enter"&&v){ addLabel(v); }
192	      });
193	    }
194	  }
195	  function addLabel(l){ if(!currentLabels.includes(l)) currentLabels.push(l); renderLabelArea();
196	    if(style==="B"){ const i=document.getElementById("chipInput"); if(i) i.focus(); } }
197	
198	  function collectLabelsForSave(){
199	    if(style==="A"){
200	      const t=document.getElementById("labelText");
201	      return t.value.split(",").map(s=>s.trim()).filter(Boolean);
202	    }
203	    return [...currentLabels];
204	  }
205	
206	  function renderList(){
207	    if(!saved.length){ cards.innerHTML='<div class="empty">Nothing saved yet.</div>'; return; }
208	    cards.innerHTML="";
209	    saved.forEach(b=>{
210	      const c=document.createElement("div"); c.className="card";
211	      c.innerHTML='<p class="title"></p><div class="url"></div>'+
212	        (b.desc?'<p class="desc"></p>':'')+
213	        (b.labels.length?'<div class="lbls"></div>':'');
214	      c.querySelector(".title").textContent=b.title;
215	      c.querySelector(".url").textContent=b.url;
216	      if(b.desc) c.querySelector(".desc").textContent=b.desc;
217	      if(b.labels.length){ const w=c.querySelector(".lbls");
218	        b.labels.forEach(l=>{const s=document.createElement("span"); s.textContent=l; w.appendChild(s);}); }
219	      cards.appendChild(c);
220	    });
221	  }
222	
223	  function startAdd(){
224	    const url=urlInput.value.trim(); if(!url) return; pendingUrl=url;
225	    fields.classList.remove("show"); fetching.classList.add("show");
226	    setTimeout(()=>{ const m=lookup(url); titleF.value=m.title; descF.value=m.desc;
227	      currentLabels=[]; renderLabelArea();
228	      fetching.classList.remove("show"); fields.classList.add("show");
229	      titleF.focus(); titleF.select(); },650);
230	  }
231	  addBtn.addEventListener("click",startAdd);
232	  urlInput.addEventListener("keydown",e=>{if(e.key==="Enter")startAdd();});
233	  saveBtn.addEventListener("click",()=>{
234	    saved.unshift({url:pendingUrl,title:titleF.value.trim(),desc:descF.value.trim(),
235	      labels:collectLabelsForSave()});
236	    urlInput.value="";titleF.value="";descF.value="";currentLabels=[];pendingUrl="";
237	    fields.classList.remove("show"); renderList(); urlInput.focus();
238	  });
239	  cancelBtn.addEventListener("click",()=>{ fields.classList.remove("show");
240	    titleF.value="";descF.value="";currentLabels=[]; urlInput.focus(); });
241	
242	  renderList();
243	</script>
244	</body>
245	</html>
