22	  .active .fchip button { border:0; background:transparent; color:var(--accent);
23	            cursor:pointer; font-size:14px; line-height:1; padding:0; }
24	  .active .clear { border:0; background:transparent; color:var(--accent);
25	            cursor:pointer; text-decoration:underline; font-size:13px; }
26	
27	  .layout { display:flex; max-width:1040px; margin:0 auto; gap:24px; padding:22px; align-items:flex-start; }
28	  .side { width:210px; flex:none; background:#fff; border:1px solid var(--line);
29	          border-radius:12px; padding:12px; position:sticky; top:22px; }
