42	  .card { background:#fff; border:1px solid var(--line); border-radius:10px;
43	          padding:14px 16px; margin-bottom:10px; }
44	  .card .title { font-size:15px; font-weight:600; margin:0 0 2px; }
45	  .card .url { font-size:12px; color:var(--accent); word-break:break-all; }
46	  .card .desc { font-size:13px; color:#3a3a42; margin:8px 0 0; }
47	  .card .lbls { margin-top:8px; display:flex; gap:6px; flex-wrap:wrap; }
48	  .card .lbls span { background:#eef0f4; color:#444; border-radius:12px; padding:2px 9px;
