56	<body>
57	  <div class="top">
58	    <h1>My Bookmarks</h1>
59	    <div class="searchbar">
60	      <span class="icon">⌕</span>
61	      <input id="search" type="text" placeholder="Search everything — titles, descriptions, addresses, labels…" autocomplete="off" />
62	    </div>
63	    <div class="active" id="activeRow"></div>
64	  </div>
65	
66	  <div class="layout">
67	    <div class="side">
68	      <h2>Labels</h2>
69	      <div id="labels"></div>
70	      <div class="all"><div class="lbl" id="showAll">All bookmarks <span class="n" id="allN"></span></div></div>
71	    </div>
72	    <div class="main">
73	      <div class="count" id="count"></div>
74	      <div id="cards"></div>
75	    </div>
76	  </div>
77	
78	<script>
79	  // A month's worth of saved bookmarks.
80	  const DATA = [
81	    {t:"Simplest Brothy Beans and Rice", u:"smittenkitchen.com/beans",
82	     d:"A weeknight one-pot dinner: creamy beans simmered with garlic and herbs over rice.", l:["recipes","dinner"]},
83	    {t:"Sheet-Pan Chicken with Lemon and Potatoes", u:"cooking.nytimes.com/sheet-pan-chicken",
84	     d:"Everything roasts on one tray for an easy dinner with almost no cleanup.", l:["recipes","dinner"]},
85	    {t:"The Best Banana Bread", u:"kingarthurbaking.com/banana-bread",
86	     d:"A moist, deeply banana-flavored loaf. Uses very ripe bananas and a little brown butter.", l:["recipes","baking"]},
87	    {t:"Overnight Oats, Five Ways", u:"minimalistbaker.com/overnight-oats",
88	     d:"Make-ahead breakfast you assemble the night before. No cooking required.", l:["recipes","breakfast"]},
89	    {t:"ripgrep — recursively search directories for a regex pattern", u:"github.com/BurntSushi/ripgrep",
90	     d:"A line-oriented search tool that recursively searches your directory for a regex pattern, respecting gitignore.", l:["tools","coding"]},
91	    {t:"Use The Index, Luke — a guide to database performance", u:"use-the-index-luke.com",
92	     d:"How database indexes work and how to design them so your queries stay fast as data grows.", l:["coding","reference"]},
93	    {t:"Figma: the collaborative interface design tool", u:"figma.com",
94	     d:"Design, prototype, and gather feedback all in one place.", l:["design","tools","work"]},
95	    {t:"How to Read More Books This Year", u:"nytimes.com/read-more-books",
96	     d:"Practical habits from lifelong readers for fitting more reading into a busy schedule.", l:["reading","articles"]},
97	    {t:"The Case for Slow Reading", u:"theatlantic.com/slow-reading",
98	     d:"A longform essay on why reading slowly and rereading can matter more than volume.", l:["reading","articles"]},
99	    {t:"A Perfect Day in Kyoto", u:"nationalgeographic.com/kyoto",
100	     d:"A walking itinerary through temples, gardens, and the best places to eat along the way.", l:["travel"]},
101	    {t:"How to Find Cheap Flights", u:"nomadicmatt.com/cheap-flights",
102	     d:"Strategies for tracking fares, using flexible dates, and booking at the right time.", l:["travel","finance"]},
103	    {t:"Obsidian — a knowledge base that works on local Markdown files", u:"obsidian.md",
104	     d:"A note-taking app for linking your thinking, stored as plain files you own.", l:["tools","reference"]},
105	    {t:"Raycast — a blazingly fast launcher", u:"raycast.com",
106	     d:"Control your tools with a few keystrokes: launch apps, run scripts, search everything.", l:["tools"]},
107	    {t:"A Beginner's Marathon Training Plan", u:"runnersworld.com/marathon-plan",
108	     d:"An 18-week schedule building from a base of a few miles up to race day.", l:["health"]},
109	    {t:"Why We Sleep, summarized", u:"blas.com/why-we-sleep",
110	     d:"Key takeaways on how sleep affects memory, mood, and long-term health.", l:["health","reading"]},
111	    {t:"The Cost of Living Alone, Explained", u:"vox.com/cost-of-living-alone",
112	     d:"How housing and everyday expenses add up differently for solo households.", l:["finance","articles"]},
113	    {t:"A Field Guide to Houseplants That Survive Neglect", u:"gardenista.com/tough-houseplants",
114	     d:"Low-light, low-water plants that tolerate a forgetful owner.", l:["garden","home"]},
115	    {t:"Best Noise-Cancelling Headphones", u:"wirecutter.com/headphones",
116	     d:"Independent testing of the top picks for commuting, focus, and travel.", l:["shopping","reference"]},
117	    {t:"An Interactive Introduction to CSS Grid", u:"css-tricks.com/css-grid",
118	     d:"Learn grid layout by example, with live editable demos for each property.", l:["coding","reference","design"]},
119	    {t:"Homemade Pizza Dough, No-Knead", u:"kingarthurbaking.com/pizza-dough",
120	     d:"A slow-rise dough you mix in minutes for a weekend dinner. Rests overnight.", l:["recipes","baking","dinner"]}
121	  ];
122	
123	  const norm = s => s.toLowerCase();
124	  // label -> count
125	  const counts = {};
126	  DATA.forEach(b=>b.l.forEach(l=>counts[l]=(counts[l]||0)+1));
127	  const allLabels = Object.keys(counts).sort((a,b)=>counts[b]-counts[a] || a.localeCompare(b));
128	
129	  let activeLabels = new Set();
130	  let query = "";
131	
132	  const labelsEl=document.getElementById("labels"), cardsEl=document.getElementById("cards"),
133	        countEl=document.getElementById("count"), activeRow=document.getElementById("activeRow"),
134	        searchEl=document.getElementById("search"), showAll=document.getElementById("showAll"),
135	        allN=document.getElementById("allN");
136	  allN.textContent=DATA.length;
137	
138	  function renderLabels(){
139	    labelsEl.innerHTML="";
140	    allLabels.forEach(l=>{
141	      const d=document.createElement("div");
142	      d.className="lbl"+(activeLabels.has(l)?" on":"");
143	      d.innerHTML='<span>'+l+'</span><span class="n">'+counts[l]+'</span>';
144	      d.addEventListener("click",()=>{ activeLabels.has(l)?activeLabels.delete(l):activeLabels.add(l); render(); });
145	      labelsEl.appendChild(d);
146	    });
147	    showAll.classList.toggle("on", activeLabels.size===0 && !query);
148	  }
149	
150	  function matchesQuery(b,q){
151	    if(!q) return true;
152	    const hay=[b.t,b.d,b.u,...b.l].join(" ").toLowerCase();
153	    return q.split(/\s+/).filter(Boolean).every(term=>hay.includes(term));
154	  }
155	  function hasAllLabels(b){ for(const l of activeLabels) if(!b.l.includes(l)) return false; return true; }
156	
157	  function hl(text,q){
158	    if(!q) return escapeHtml(text);
159	    let out=escapeHtml(text);
160	    q.split(/\s+/).filter(Boolean).forEach(term=>{
161	      const re=new RegExp("("+term.replace(/[.*+?^${}()|[\]\\]/g,"\\$&")+")","ig");
162	      out=out.replace(re,"<mark>$1</mark>");
163	    });
164	    return out;
165	  }
166	  function escapeHtml(s){ return s.replace(/[&<>]/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;"}[c])); }
167	
168	  function render(){
169	    const q=norm(query.trim());
170	    const results=DATA.filter(b=>hasAllLabels(b) && matchesQuery(b,q));
171	
172	    // active filter row
173	    activeRow.innerHTML="";
174	    if(activeLabels.size===0 && !q){ activeRow.textContent="Showing everything."; }
175	    else {
176	      [...activeLabels].forEach(l=>{
177	        const c=document.createElement("span"); c.className="fchip";
178	        c.innerHTML=l+' <button title="remove">×</button>';
179	        c.querySelector("button").addEventListener("click",()=>{activeLabels.delete(l);render();});
180	        activeRow.appendChild(c);
181	      });
182	      if(q){ const c=document.createElement("span"); c.className="fchip";
183	        c.innerHTML='“'+escapeHtml(query.trim())+'” <button title="clear">×</button>';
184	        c.querySelector("button").addEventListener("click",()=>{query="";searchEl.value="";render();});
185	        activeRow.appendChild(c); }
186	      const clr=document.createElement("button"); clr.className="clear"; clr.textContent="clear all";
187	      clr.addEventListener("click",()=>{activeLabels.clear();query="";searchEl.value="";render();});
188	      activeRow.appendChild(clr);
189	    }
190	
191	    countEl.textContent = results.length+(results.length===1?" bookmark":" bookmarks")+
192	      (activeLabels.size||q ? " match" : "");
193	
194	    if(!results.length){
195	      cardsEl.innerHTML='<div class="empty">Nothing matches that yet.<br>Try removing a label or a search word.</div>';
196	      renderLabels(); return;
197	    }
198	    cardsEl.innerHTML="";
199	    results.forEach(b=>{
200	      const c=document.createElement("div"); c.className="card";
201	      c.innerHTML='<p class="title">'+hl(b.t,q)+'</p>'+
202	        '<div class="url">'+hl(b.u,q)+'</div>'+
203	        '<p class="desc">'+hl(b.d,q)+'</p>'+
204	        '<div class="lbls">'+b.l.map(l=>'<span class="'+(activeLabels.has(l)?"match":"")+'" data-l="'+l+'">'+l+'</span>').join('')+'</div>';
205	      c.querySelectorAll("[data-l]").forEach(s=>s.addEventListener("click",()=>{
206	        const l=s.dataset.l; activeLabels.has(l)?activeLabels.delete(l):activeLabels.add(l); render();
207	      }));
208	      cardsEl.appendChild(c);
209	    });
210	    renderLabels();
211	  }
212	
213	  searchEl.addEventListener("input",e=>{ query=e.target.value; render(); });
214	  showAll.addEventListener("click",()=>{ activeLabels.clear(); query=""; searchEl.value=""; render(); });
215	  render();
216	</script>
